#!/bin/sh
# D-025 merge: full site build, fresh fast mains, full sweep, publish, checks.
S="$1"; P='H:/Projects/MathsPhysicsEcosystem/PrincipiaMetaphysica'; E='H:/Projects/MathsPhysicsEcosystem/metaphysica'
R="${RUNS:-H:/claude-scratch/runs_d}"; L="$S/merge_d025.log"  # runs stay off C: (it filled up, 2026-10-25)
export PYTHONIOENCODING=utf-8
stat() { python -c "import json;s=json.load(open('$1/AutoGenerated/statistics.json',encoding='utf-8'))['framework_statistics'];print(s['chi_squared'],s['degrees_of_freedom'])"; }
cd /c
mkdir -p "$R"
python -m metaphysica.build --out "$P" --keep-going > "$S/main_build_d.log" 2>&1; echo "site exit=$? stats=$(stat $P)" >> $L
python -m metaphysica.build --out "$R/active" --fast --keep-going > "$R/active.log" 2>&1; echo "active stats=$(stat $R/active)" >> $L
[ "$(stat $R/active | cut -d' ' -f2)" = "$(stat $P | cut -d' ' -f2)" ] || { echo "GATE FAILED: fresh dof differs from site" >> $L; exit 3; }
python -m metaphysica.build --out "$R/active2" --fast --keep-going > "$R/active2.log" 2>&1; echo "active2 stats=$(stat $R/active2)" >> $L
python "$P/docs/plan/paths/sweep.py" "$R" > "$R/sweep.out" 2>&1; echo "sweep: $(tail -1 $R/sweep.out)" >> $L
python -m metaphysica.testground paths-publish --theory pm --main-run "$P" --volatile-run "$R/active" "$R/active2" --runs "$R" --published "$P" --out "$P/AutoGenerated/paths" > "$R/publish.log" 2>&1; echo "publish: $(tail -1 $R/publish.log)" >> $L
cp "$E/src/metaphysica/data/path_comparison.json" "$S/path_comparison.before.json"
python -m metaphysica.simulations.PM.paper.path_snapshot "$P/AutoGenerated/paths" > /dev/null 2>&1
python -c "
import json;a=json.load(open('$S/path_comparison.before.json'))['paths'];b=json.load(open('$E/src/metaphysica/data/path_comparison.json'))['paths']
print('snapshot figures', 'UNCHANGED' if a==b else 'CHANGED: %s -> %s' % (a,b))" >> $L
python "$P/docs/plan/paths/site_check.py" "$P" "$S/bar_d.png" > "$R/site_check.log" 2>&1; echo "site_check: $(grep -c ^PASS $R/site_check.log) PASS, $(grep -c ^FAIL $R/site_check.log) FAIL" >> $L
cd "$E" && METAPHYSICA_OUT="$P" python -m pytest -q -p no:cacheprovider tests/test_reference_identifier_targets.py tests/test_core_paper.py tests/test_superseded_geometry_prose.py tests/test_path_snapshot.py tests/test_geometry_to_physics.py tests/test_published_formula_coverage.py tests/test_option_status.py > "$R/tests.log" 2>&1; echo "tests: $(tail -1 $R/tests.log)" >> $L
for f in $(cd "$E/src/metaphysica/website" && find index.html Pages js css foundations -type f); do cmp -s "$E/src/metaphysica/website/$f" "$P/$f" || echo "bundle/site differ: $f" >> $L; done
echo "end" >> $L
